# -*- coding: utf-8 -*-
from pathlib import Path
import json
def series_chart(name,splo,sphi,spticks,marks):
 d=json.loads((Path(__file__).resolve().parent/name).read_text(encoding='utf-8'));rows=d['rows'];n=len(rows)
 L,R,T,B=90,1110,22,272;W=R-L;H=B-T
 x=lambda i:L+W*i/(n-1)
 def line(key,lo,hi):
  return ' '.join(('M' if i==0 else 'L')+f"{x(i):.1f} {B-H*(r[key]-lo)/(hi-lo):.1f}" for i,r in enumerate(rows))
 years=''.join(f'<text class="ax" x="{x(i):.0f}" y="{B+34}" text-anchor="start">{r["month"][:4]}</text><line class="tick" x1="{x(i):.1f}" y1="{B}" x2="{x(i):.1f}" y2="{B+10}"/>' for i,r in enumerate(rows) if r['month'].endswith('-01'))
 grid=''.join(f'<line class="grid" x1="{L}" y1="{B-H*v/6:.1f}" x2="{R}" y2="{B-H*v/6:.1f}"/><text class="ax gold" x="{L-14}" y="{B-H*v/6+7:.1f}" text-anchor="end">{v}%</text>' for v in (0,2,4,6))
 right=''.join(f'<text class="ax teal" x="{R+14}" y="{B-H*(v-splo)/(sphi-splo)+7:.1f}">{v:,}</text>' for v in spticks)
 def mark(i,key,lo,hi,label,dx,dy,anchor):
  return f'<circle class="dot" cx="{x(i):.1f}" cy="{B-H*(rows[i][key]-lo)/(hi-lo):.1f}" r="7"/><text class="note" x="{x(i)+dx:.1f}" y="{B-H*(rows[i][key]-lo)/(hi-lo)+dy:.1f}" text-anchor="{anchor}">{label}</text>'
 ms=''.join(mark(i,key,0 if key=='fedfunds' else splo,6 if key=='fedfunds' else sphi,label,dx,dy,anchor) for i,key,label,dx,dy,anchor in marks)
 return f'<svg class="series" viewBox="0 0 1200 320" aria-label="{d["episode"]}">{grid}{years}{right}<path class="line teal" pathLength="1" d="{line("sp500_month_end",splo,sphi)}"/><path class="line gold" pathLength="1" d="{line("fedfunds",0,6)}"/>{ms}</svg>'
b=Path(__file__).resolve().parent.parent
slides=[]
def add(ch,content,cls=''):
 slides.append(f'<section class="slide {cls}" data-ch="{ch}">{content}</section>')
def head(n,title,sub=''):
 return f'<div class="eyebrow">{n}</div><h2>{title}</h2>'+ (f'<p class="lead">{sub}</p>' if sub else '')
def cards(items):
 return '<div class="cards">'+''.join(f'<article><small>{a}</small><h3>{c}</h3><p>{d}</p></article>' for a,c,d in items)+'</div>'
def question(ch,q,a,art='',op=.42):
 bg=f'<div class="answer-art" style="background-image:url(\'{art}\');--art-opacity:{op}" aria-hidden="true"></div><div class="answer-shade" aria-hidden="true"></div>' if art else ''
 add(ch,bg+'<div class="question"><span class="tag">考えてみてください</span><h2>'+q+'</h2><div class="cover-wrap"><div class="answer">'+a+'</div><button class="cover" type="button">クリックで開く</button></div></div>','think')
add(0,'''<div class="city"></div><svg class="currents" viewBox="0 0 1440 810" aria-hidden="true"><path d="M550 820C700 650 820 660 920 515S1100 420 1480 390"/><path d="M520 840C760 670 780 590 950 590S1120 650 1480 535"/><path d="M680 850C820 710 990 755 1100 540S1280 330 1500 270"/></svg><div class="title-copy"><div class="eyebrow">ニュースと経済がわかるシリーズ ｜ 第5回</div><h1>金利が動くと、<br>何が起きる？</h1><p class="subtitle">債券と株式の関係を、歴史でたどる</p><div class="rule"></div><p class="catch">金利が変わる。<br><em>お金の行き先が変わる。</em></p></div><div class="title-foot"><span>第1〜4回のダイジェストとともに</span><span>ALPHA Base ｜ 西村 真</span></div>''','title')
add(0,head('RECAP｜4回分を、ひとつの地図に','ここまでの4つの視点。')+cards([('01 マクロ経済','外の環境を読む','景気・物価・為替。<br>会社を取り巻く天気を見る。'),('02 株式の基礎','会社の持分を持つ','事業の挑戦を支え、<br>成果とリスクを分け合う。'),('03 株価のしくみ','期待が値段になる','利益と将来への見方が、<br>売り買いを通じて価格になる。'),('04 バブルと暴落','期待は、揺らぐ','値上がりの先に、<br>買い手がいるとは限らない。')]),'recap')
add(0,head('第5回でつながること','その期待を支える、<br>お金の条件。','借りるときの負担。貸すときの見返り。<br>その両方に関わるのが、金利。')+'<div class="route"><span>経済</span><i>→</i><span>企業</span><i>→</i><span>期待</span><i>→</i><span>値段</span></div><div class="underbar">金利は、この流れ全体に関わっている。</div>')
add(0,head('今日の見方','金利のニュースは、<br>二つの問いで聞く。')+'''<div class="two-q"><div><small>問い 1</small><h3>なぜ今、<br>金利が動いたのか。</h3></div><div><small>問い 2</small><h3>その変化は、<br>どこに影響するのか。</h3></div></div><div class="chips"><small>金利がつながる先</small><span>借りる負担</span><span>預金の利息</span><span>企業の資金調達</span><span>債券の価格</span><span>株式の評価</span></div>''','views')
add(1,head('01｜お金のレンタル料','金利とは、<br>お金を使うための値段。','借りる側には「負担」。<br>貸す側には「見返り」。'),'chapter')
add(1,head('01-1｜同じ100万円でも','金利が変わると、負担が変わる。')+'''<div class="rate-demo"><div class="rate-control"><small>100万円を1年間借りる</small><strong id="rate">1<span>%</span></strong><div class="choices"><button data-rate="1" aria-pressed="true">年1%</button><button data-rate="3" aria-pressed="false">年3%</button><button data-rate="5" aria-pressed="false">年5%</button></div><p>借りる金額が同じでも、<br>金利が上がるほど、<br>利息の重しは増えていく。</p></div><div class="interest"><small>1年間の利息</small><strong id="cost">1万円</strong><svg class="weight" id="weight" viewBox="0 0 520 250" style="--n:1" aria-label="元金の上に利息の重しが乗る図"><line class="ground" x1="60" y1="242" x2="460" y2="242"/><g class="spring"><path d="M260 242 L260 232 L232 222 L288 212 L232 202 L288 192 L260 184"/></g><g class="load"><rect class="plank" x="90" y="176" width="340" height="22" rx="6"/><text class="plank-label" x="260" y="192">借りた元金 100万円</text><g class="weights"><g class="w" style="--i:0"><rect x="200" y="138" width="120" height="34" rx="5"/><text x="260" y="161">1万円</text></g><g class="w" style="--i:1"><rect x="200" y="100" width="120" height="34" rx="5"/><text x="260" y="123">1万円</text></g><g class="w" style="--i:2"><rect x="200" y="62" width="120" height="34" rx="5"/><text x="260" y="85">1万円</text></g><g class="w" style="--i:3"><rect x="200" y="24" width="120" height="34" rx="5"/><text x="260" y="47">1万円</text></g><g class="w" style="--i:4"><rect x="200" y="-14" width="120" height="34" rx="5"/><text x="260" y="9">1万円</text></g></g></g></svg></div></div><p class="fine">元金を1年間据え置き、手数料を含めずに比較。重し1つ＝利息1万円。</p>''','demo')
question(1,'金利が上がると、<br>お金の使い方は変わる？','借りる負担が増える一方、<br>貯める・貸すことの魅力も変わる。','assets/rate05/interest-city-v1.png')
add(1,'<div class="city"></div><div class="hero-copy">金利が変わる。<br><em>お金の行き先が変わる。</em></div>','scene')
add(2,head('02｜もう一つの資産、債券','会社の持分を買う。お金を貸す。')+'''<div class="choices lab-modes"><button data-mode="stock" aria-pressed="true">株式で支える</button><button data-mode="bond" aria-pressed="false">債券で支える</button></div><div class="lab-stage" id="lab" data-mode="stock" data-step="0"><div class="node you"><b>あなた</b><small>投資家</small></div><div class="node firm"><b>会社</b><small>発行体</small></div><div class="path"></div><div class="token coin c1"></div><div class="token coin c2"></div><div class="token coin c3"></div><div class="token share"><i></i><span>持分</span></div><div class="token note"><i></i><span>約束</span></div><div class="token small d1"></div><div class="token small d2"></div><div class="token small d3"></div><div class="token principal"><span>元本</span></div><div class="tag-year y1">1年目</div><div class="tag-year y2">2年目</div><div class="tag-year y3">3年目</div><div class="flow-label give">お金を渡す</div></div><div class="lab-caption"><div><span class="lab-count" id="lab-count">場面 1 / 3</span><p id="lab-text"></p></div><button class="lab-next" id="lab-next">次の場面 →</button></div>''','lab')
add(2,head('02-1｜債券のきほん','お金を貸して、約束を受け取る。')+'''<div class="bond-route"><div><small>買うとき</small><h3>投資家 → 発行体</h3><p>お金を渡す</p></div><b>→</b><div><small>保有する間</small><h3>利息を受け取る</h3><p>利払いの条件に従う</p></div><b>→</b><div><small>満期</small><h3>元本が返る</h3><p>発行体の返済能力が大切</p></div></div><p class="underbar">満期までの約束と、途中で売れる値段は別の話。</p>''')
