add(3,'<div class="city harbor"><video muted playsinline preload="auto" poster="assets/rate05/bond-harbor-v1.jpg" aria-hidden="true"><source src="assets/rate05/bond-harbor-v1.mp4" type="video/mp4"></video></div><div class="hero-copy">約束は、変わらない。<br><em>比べる相手が、変わる。</em></div>','scene')
add(3,head('03｜金利と債券価格','同じ約束でも、比較相手が変わる。')+'''<div class="choices yield"><button data-yield="1" aria-pressed="false">市場金利が上がる</button><button data-yield="0" aria-pressed="true">いまのまま</button><button data-yield="-1" aria-pressed="false">市場金利が下がる</button></div><svg class="scale" id="scale" viewBox="0 0 1200 300" style="--a:0deg" aria-label="持っている債券と新しい債券を比べる天秤"><path class="base" d="M540 282 H660"/><line class="post" x1="600" y1="282" x2="600" y2="70"/><g class="beam"><line class="bar" x1="290" y1="70" x2="910" y2="70"/><g class="pan pan-l"><line class="hang" x1="0" y1="0" x2="0" y2="150"/><path class="dish" d="M-130 150 Q0 190 130 150"/><text class="pan-title" y="-16">持っている債券</text><text class="pan-sub" y="118">毎年の利息</text><g class="coins" id="coins-old"><circle class="coin on" cx="-28" cy="140" r="12"/><circle class="coin on" cx="0" cy="140" r="12"/><circle class="coin on" cx="28" cy="140" r="12"/></g></g><g class="pan pan-r"><line class="hang" x1="0" y1="0" x2="0" y2="150"/><path class="dish" d="M-130 150 Q0 190 130 150"/><text class="pan-title" y="-16">新しく出る債券</text><text class="pan-sub" y="118">毎年の利息</text><g class="coins" id="coins-new"><circle class="coin on" data-i="0" cx="-56" cy="140" r="12"/><circle class="coin on" data-i="1" cx="-28" cy="140" r="12"/><circle class="coin on" data-i="2" cx="0" cy="140" r="12"/><circle class="coin" data-i="3" cx="28" cy="140" r="12"/><circle class="coin" data-i="4" cx="56" cy="140" r="12"/></g></g></g><circle class="pivot" cx="600" cy="70" r="9"/></svg><div class="scale-notes"><div class="pricetag"><small>持っている債券の値段</small><strong><s id="old-price"></s><em id="cur-price">100万円</em></strong></div><p id="scale-note">利息が同じなら、同じ値段で釣り合う。</p></div><p class="fine">信用力や残存期間など、ほかの条件が同じ場合。利息の数と値段は説明用の目安。</p>''','scale-page')
add(4,head('04｜金利と株価','株価に届く、3つの道すじ。')+'''<div class="choices dir"><button data-dir="1" aria-pressed="true">金利が上がる</button><button data-dir="-1" aria-pressed="false">金利が下がる</button></div><svg class="routes" id="routes" viewBox="0 0 1200 250" aria-label="金利から株価への3つの経路"><path id="r1" class="route" d="M180 125 C 400 20, 800 20, 1020 125"/><path id="r2" class="route" d="M180 125 L 1020 125"/><path id="r3" class="route" d="M180 125 C 400 230, 800 230, 1020 125"/><g class="node"><circle cx="110" cy="125" r="60"/><text x="110" y="134">金利</text><text class="mark" id="rate-mark" x="110" y="42">↑</text></g><g class="node stock"><circle cx="1090" cy="125" r="60"/><text x="1090" y="134">株価</text><text class="mark" id="stock-mark" x="1090" y="42">↓</text></g><g class="rlabel" data-route="1"><rect x="500" y="26" width="200" height="44" rx="22"/><text x="600" y="55">1 企業の利益</text></g><g class="rlabel" data-route="2"><rect x="500" y="103" width="200" height="44" rx="22"/><text x="600" y="132">2 資産の比較</text></g><g class="rlabel" data-route="3"><rect x="500" y="180" width="200" height="44" rx="22"/><text x="600" y="209">3 将来の評価</text></g><circle class="pulse" r="9"><animateMotion id="pm" dur="1.8s" begin="indefinite" fill="freeze" calcMode="spline" keySplines=".4 0 .2 1" keyTimes="0;1"><mpath href="#r1"/></animateMotion></circle></svg><div class="route-notes"><small id="route-kicker">道すじを選んでください</small><p id="route-text">金利の変化は、3つの道すじで株価に届く。同時に働き、強さは局面で変わる。</p></div><p class="fine">「利上げなら必ず株安」とは限らない。理由と期待も見る。</p>''','routes-page')
add(4,head('04-1｜歴史でたどる','同じ金利の変化でも、背景は違う。')+cards([('物価が上がるとき','物価を抑えたい','金融引締めと、<br>企業の利益への影響を追う。'),('景気が弱るとき','景気を支えたい','金融緩和と、<br>先行きへの不安を分けて見る。'),('期待が先に動くとき','発表前から織り込む','金利の水準だけでなく、<br>予想との違いを確かめる。')]))
add(4,head('04-2｜物価が上がるとき','2022年、利上げは1年半続いた。')+'''<div class="chart"><div class="legend"><span class="gold">政策金利（米・実効FF金利）</span><span class="teal">株価（S&amp;P500・月末）</span></div>'''+series_chart('系列_2022利上げ.json',3400,4900,(3500,4000,4500),[(14,'fedfunds','2022年3月 利上げ開始',-16,-16,'end'),(21,'sp500_month_end','2022年10月 株価の底',18,8,'start'),(30,'fedfunds','2023年7月 最後の利上げ',0,-22,'middle')])+'''</div><div class="chart-notes"><div><small>物価</small><p>前年比7〜9%まで上昇。<br>抑えるための利上げだった。</p></div><div><small>株価</small><p>利上げの前から下がり始め、<br>利上げが続く途中で戻り始めた。</p></div><div><small>見方</small><p>金利の水準だけでなく、<br>「いつ止まるか」の予想が値段に入る。</p></div></div><p class="fine">出典：FRED（FEDFUNDS, SP500, CPIAUCSL）。月次、2021〜2023年。株価の動きには企業利益や期待の変化も関わる。</p>''','history')
add(4,head('04-3｜期待が先に動くとき','2024年、利下げは予想され、株価は先に動いた。')+'''<div class="chart"><div class="legend"><span class="gold">政策金利（米・実効FF金利）</span><span class="teal">株価（S&amp;P500・月末）</span></div>'''+series_chart('系列_2024利下げ.json',4500,7000,(5000,6000,7000),[(8,'fedfunds','2024年9月 利下げ開始',-16,32,'end'),(15,'sp500_month_end','2025年4月 関税不安で下落',18,26,'start'),(20,'fedfunds','2025年9月 利下げ再開',-16,32,'end')])+'''</div><div class="chart-notes"><div><small>物価</small><p>3%前後まで落ち着き、<br>利下げの余地ができた。</p></div><div><small>株価</small><p>利下げの前から上がり、後も続いた。<br>2025年春の下げは、関税不安が主因。</p></div><div><small>見方</small><p>「利下げなら株高」とも限らない。<br>理由が景気の弱さなら、話は別。</p></div></div><p class="fine">出典：FRED（FEDFUNDS, SP500, CPIAUCSL）。月次、2024〜2025年。株価の動きには企業利益や期待の変化も関わる。</p>''','history')
add(5,head('05｜ニュースで見ておきたい','まずは、3つの数字をつなぐ。')+cards([('01','政策金利','中央銀行は、<br>どう動こうとしているか。'),('02','長期金利','市場は、先の景気や物価を<br>どう見ているか。'),('03','物価上昇率','お金の購買力は、<br>どう変わっているか。')]))
add(5,head('総まとめ｜第1回から第5回へ','ニュースを、一本のつながりで読む。')+'''<div class="final-map"><span>経済の変化</span><i>→</i><span>企業の利益</span><i>→</i><span>将来への期待</span><i>→</i><span>売り買いと価格</span></div><div class="final-anchor">金利という、もう一つの軸。</div><p class="lead">何が変わったのか。誰に影響するのか。<br>その期待は、すでに値段に入っているのか。</p>''')
