script='''const slides=[...document.querySelectorAll('.slide')],nav=[...document.querySelectorAll('nav button')];let current=0;function show(n){if(n<0||n>=slides.length)return;current=n;slides.forEach((s,i)=>{s.classList.toggle('on',i===n);s.inert=i!==n;s.querySelectorAll('video').forEach(v=>{if(i===n&&!matchMedia('(prefers-reduced-motion: reduce)').matches){v.currentTime=0;v.play().catch(()=>{})}else v.pause()})});nav.forEach(b=>b.classList.toggle('active',b.dataset.ch===slides[n].dataset.ch));document.querySelector('#count').textContent=(n+1)+' / '+slides.length}let lockedUntil=0;function step(d){if(performance.now()<lockedUntil)return;const s=slides[current];if(s.querySelector('.cover')){if(d>0&&!s.classList.contains('revealed')){s.classList.add('revealed');lockedUntil=performance.now()+850;return}if(d<0&&s.classList.contains('revealed')){s.classList.remove('revealed');return}}show(current+d)}document.querySelector('#next').onclick=()=>step(1);document.querySelector('#prev').onclick=()=>step(-1);nav.forEach(b=>b.onclick=()=>show(slides.findIndex(s=>s.dataset.ch===b.dataset.ch)));document.querySelectorAll('.cover').forEach(c=>c.onclick=e=>{e.stopPropagation();c.blur();step(1)});addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||e.repeat)return;const btn=e.target.closest('button');if(btn&&!btn.classList.contains('cover')&&[' ','Enter'].includes(e.key))return;if(['ArrowRight','PageDown',' ','Enter'].includes(e.key)){e.preventDefault();step(1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();step(-1)}if(e.key==='Home')show(0)});function setRate(n){document.querySelectorAll('[data-rate]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.rate==n));document.querySelector('#rate').innerHTML=n+'<span>%</span>';document.querySelector('#cost').textContent=n+'万円';const w=document.querySelector('#weight');w.style.setProperty('--n',n);w.querySelectorAll('.w').forEach((g,i)=>g.classList.toggle('on',i<n));const ld=w.querySelector('.load');ld.classList.remove('thud');clearTimeout(ld._t);ld._t=setTimeout(()=>ld.classList.add('thud'),n*120+450)}document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>setRate(Number(b.dataset.rate)));setRate(1);const labText={stock:['お金を渡して、会社の持分（株式）を受け取る。<br>会社の共同オーナーになる。','事業がうまくいけば、持分の価値は上がる。<br>利益の分配（配当）を受け取ることもある。','うまくいかなければ、持分の価値は下がる。<br>成果もリスクも分け合うのが、株式。'],bond:['お金を貸して、約束（債券）を受け取る。<br>決めた利息と、満期に元本を返す約束。','決めた利息が、決めた日に届く。<br>会社の業績が良くても悪くても、金額は同じ。','満期。貸した元本が戻ってくる。<br>前提は、発行体が返せること。']};const lab=document.querySelector('#lab');let labStep=0;function labRender(){const m=lab.dataset.mode;lab.dataset.step='';lab.classList.remove('bright','dim');void lab.offsetWidth;lab.dataset.step=labStep;if(m==='stock'&&labStep===1)lab.classList.add('bright');if(m==='stock'&&labStep===2)lab.classList.add('dim');document.querySelector('#lab-text').innerHTML=labText[m][labStep];document.querySelector('#lab-count').textContent='場面 '+(labStep+1)+' / 3';document.querySelector('#lab-next').textContent=labStep<2?'次の場面 →':'最初から'}document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',x===b));lab.dataset.mode=b.dataset.mode;labStep=0;labRender()});document.querySelector('#lab-next').onclick=()=>{labStep=(labStep+1)%3;labRender()};labRender();const scale=document.querySelector('#scale');const scaleNote={'1':['新しい債券のほうが利息が多い。<br>天秤は、新しい方へ傾く。','持っている債券は、値段を下げてはじめて選ばれる。<br>値段で、また釣り合う。'],'0':['利息が同じなら、同じ値段で釣り合う。'],'-1':['新しい債券のほうが利息が少ない。<br>天秤は、持っている方へ傾く。','持っている債券は、値段が上がっても選ばれる。<br>値段で、また釣り合う。']};let scaleTimer=0;document.querySelectorAll('[data-yield]').forEach(b=>b.onclick=()=>{const d=b.dataset.yield;document.querySelectorAll('[data-yield]').forEach(x=>x.setAttribute('aria-pressed',x===b));clearTimeout(scaleTimer);const n={'1':5,'0':3,'-1':1}[d];scale.querySelectorAll('#coins-new .coin').forEach((c,i)=>c.classList.toggle('on',i<n));scale.style.setProperty('--a',{'1':'9deg','0':'0deg','-1':'-9deg'}[d]);document.querySelector('#scale-note').innerHTML=scaleNote[d][0];document.querySelector('#old-price').textContent='';document.querySelector('#cur-price').textContent='100万円';if(d!=='0'){scaleTimer=setTimeout(()=>{document.querySelector('#old-price').textContent='100万円';document.querySelector('#cur-price').textContent=d==='1'?'96万円':'104万円';document.querySelector('#scale-note').innerHTML=scaleNote[d][1];scale.style.setProperty('--a','0deg')},2200)}});const routeText={'1':{'1':['道すじ 1｜企業の利益','借りるコストが上がり、利益が圧迫される。<br>投資計画を先送りする会社も出てくる。'],'2':['道すじ 2｜資産の比較','債券の利回りが上がり、株より魅力的に見える。<br>お金が、株から債券へ移りやすくなる。'],'3':['道すじ 3｜将来の評価','将来の利益を今の価値に直す割引が大きくなる。<br>同じ利益でも、今の評価は下がる。']},'-1':{'1':['道すじ 1｜企業の利益','借りるコストが下がり、利益に余裕が出る。<br>投資に踏み切る会社も出てくる。'],'2':['道すじ 2｜資産の比較','債券の利回りが下がり、株の魅力が相対的に増す。<br>お金が、債券から株へ移りやすくなる。'],'3':['道すじ 3｜将来の評価','将来の利益を今の価値に直す割引が小さくなる。<br>同じ利益でも、今の評価は上がる。']}};let rDir='1',rSel='';function routeRender(){document.querySelector('#rate-mark').textContent=rDir==='1'?'↑':'↓';document.querySelector('#stock-mark').textContent=rSel?(rDir==='1'?'↓':'↑'):'?';document.querySelectorAll('.route').forEach(r=>r.classList.toggle('on',r.id==='r'+rSel));document.querySelectorAll('.rlabel').forEach(l=>l.classList.toggle('on',l.dataset.route===rSel));if(rSel){const t=routeText[rDir][rSel];document.querySelector('#route-kicker').textContent=t[0];document.querySelector('#route-text').innerHTML=t[1];const pm=document.querySelector('#pm');pm.querySelector('mpath').setAttribute('href','#r'+rSel);document.querySelector('.pulse').classList.add('go');pm.beginElement()}}document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>{rDir=b.dataset.dir;document.querySelectorAll('[data-dir]').forEach(x=>x.setAttribute('aria-pressed',x===b));routeRender()});document.querySelectorAll('.rlabel').forEach(l=>l.onclick=()=>{rSel=l.dataset.route;routeRender()});document.querySelector('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>{})};function fit(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1440,innerHeight/810))}addEventListener('resize',fit);fit();show(0);'''
html='<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>第5回｜金利が動くと何が起きる？</title><link rel="preload" as="image" href="assets/rate05/interest-city-v1.png"><link rel="preload" as="image" href="assets/rate05/bond-harbor-v1.jpg"><style>'+css+'</style></head><body><main id="stage"><nav aria-label="章へ移動"><b>第5回</b>'+''.join(f'<button data-ch="{i}">{t}</button>' for i,t in enumerate(['はじめに','1 金利','2 債券','3 価格','4 株価と歴史','5 総まとめ']))+'</nav>'+''.join(slides)+'<button class="fullscreen" id="fullscreen">全画面 ⛶</button><div class="pager"><button id="prev" aria-label="前へ">‹</button><span id="count"></span><button id="next" aria-label="次へ">›</button></div></main><script>'+script+'</script></body></html>'
(b/'sessions/05/index.html').write_text(html,encoding='utf-8')
